<?php
declare(strict_types=1);
namespace Hostider\Services;
use Hostider\Core\{CanonicalJson,Config,Id};use Hostider\Core\Database\Database;use Hostider\Core\Http\HttpError;use Hostider\Core\Security\{Authorization,Crypto,Principal};use Hostider\Finance\Unsigned;use Hostider\Pricing\PriceSnapshot;
/** Explicit exact-second upgrade policy; ambiguous downgrade/one-time fee cases require review. */
final readonly class PackageChanges
{
    private Repository $repository;private \Hostider\Commerce\Services $commerce;
    public function __construct(private Database $db,private Config $config){$this->repository=new Repository($db,$config);$this->commerce=new \Hostider\Commerce\Services($db,$config);}
    private function authorize(string $id,string $customer,Principal $actor): void{if($this->config->environment!=='test'){throw new HttpError(403,'F3_TEST_ONLY');}(new Authorization())->require($actor,'services.package',$customer,privileged:true,service:$id);}
    private function transaction(\Closure $work): mixed{return $this->db->pdo->inTransaction()?$work():$this->db->transaction($work);}
    private function lock(string $id,string $customer): array
    {
        $identity=$this->repository->find($id,$customer,false);$this->db->execute('SELECT id FROM orders WHERE id=? FOR UPDATE',[$identity['order_id']]);$this->db->execute('SELECT id FROM order_items WHERE id=? FOR UPDATE',[$identity['order_item_id']]);$service=$this->repository->find($id,$customer);if(!in_array($service['status'],['ACTIVE','SUSPENDED'],true)||$service['imported']){throw new HttpError(409,'SERVICE_NOT_CHANGEABLE');}return $service;
    }
    public static function prorate(string $minor,int $remaining,int $duration): string
    {
        if($duration<1||$remaining<0||$remaining>$duration){throw new HttpError(422,'INVALID_PRORATION_INTERVAL');}[$q,$r]=Unsigned::divide(Unsigned::multiply($minor,(string)$remaining),(string)$duration);return Unsigned::compare(Unsigned::multiply($r,'2'),(string)$duration)>=0?Unsigned::add($q,'1'):$q;
    }
    public function plan(string $id,string $customer,array $selection,Principal $actor,\DateTimeImmutable $now): array
    {
        $this->authorize($id,$customer,$actor);$service=$this->repository->find($id,$customer,false);$policy=(new Policies($this->db,$this->config))->resolve($service);if(Policies::required($policy,'package_proration')!=='EXACT_SECONDS'){throw new HttpError(409,'PACKAGE_PRORATION_POLICY_REQUIRED');}$period=$this->db->execute('SELECT * FROM svc_periods WHERE id=?',[$service['current_period_id']])->fetch();if(!$period||$period['status']!=='VERIFIED'||$period['ends_at']===null||!in_array($service['status'],['ACTIVE','SUSPENDED'],true)){throw new HttpError(409,'CURRENT_VERIFIED_PERIOD_REQUIRED');}
        $cycle=json_decode($period['cycle_snapshot'],true,32,JSON_THROW_ON_ERROR);if(($selection['quantity']??null)!==1||($selection['cycle_id']??null)!==$cycle['id']){throw new HttpError(422,'PACKAGE_CHANGE_PRESERVES_CYCLE_AND_SINGLE_UNIT');}$old=$this->db->execute('SELECT * FROM svc_prices WHERE id=?',[$service['current_price_id']])->fetch();$current=json_decode($old['snapshot'],true,64,JSON_THROW_ON_ERROR);$target=$this->commerce->quotes->plan($customer,new \Hostider\Finance\Currency($old['currency']),[$selection],[],$now)->jsonSerialize();$line=$target['lines'][0];$product=$this->commerce->catalog->repository->product($selection['product_id']);if($product['product_type']!=='HOSTING'||$line['activation_policy']!=='AUTO'){throw new HttpError(409,'PACKAGE_TARGET_REQUIRES_MANUAL_REVIEW');}
        foreach(array_merge($current['sources'],$line['sources']) as $source){if($source['charge_kind']==='ONCE'){throw new HttpError(409,'PACKAGE_ONE_TIME_COMPONENT_REVIEW_REQUIRED');}}
        $start=(new \DateTimeImmutable($period['starts_at'],new \DateTimeZone('UTC')))->getTimestamp();$end=(new \DateTimeImmutable($period['ends_at'],new \DateTimeZone('UTC')))->getTimestamp();$remaining=$end-$now->getTimestamp();$duration=$end-$start;if($remaining<1||$remaining>$duration){throw new HttpError(409,'PACKAGE_PERIOD_NOT_CURRENT');}$charge=$line;foreach(['net_minor','tax_minor'] as $field){if(Unsigned::compare($line[$field],(string)$old[$field])<0){throw new HttpError(409,'PACKAGE_DOWNGRADE_CREDIT_POLICY_REVIEW_REQUIRED');}$charge[$field]=self::prorate(Unsigned::subtract($line[$field],(string)$old[$field]),$remaining,$duration);}$charge['total_minor']=Unsigned::add($charge['net_minor'],$charge['tax_minor']);$charge['original_minor']=$charge['net_minor'];$charge['discount_minor']='0';$charge['promotions']=[];$quote=new PriceSnapshot(array_replace($target,['lines'=>[$charge],'net_minor'=>$charge['net_minor'],'tax_minor'=>$charge['tax_minor'],'total_minor'=>$charge['total_minor'],'promotions'=>[]]));return ['quote'=>$quote,'target'=>$line,'selection'=>$selection,'remaining_seconds'=>$remaining,'duration_seconds'=>$duration,'rounding'=>'PER_COMPONENT_HALF_UP'];
    }
    public function request(string $id,string $customer,array $selection,Principal $actor,string $trace,\DateTimeImmutable $now): array
    {
        $this->authorize($id,$customer,$actor);return $this->transaction(function()use($id,$customer,$selection,$actor,$trace,$now): array{
            $service=$this->lock($id,$customer);if($service['current_operation_id']!==null&&$this->db->execute("SELECT 1 FROM svc_operations o WHERE o.id=? AND (o.status IN ('PENDING','RUNNING') OR (o.status='UNKNOWN' AND NOT EXISTS(SELECT 1 FROM svc_resolutions r WHERE r.operation_id=o.id)))",[$service['current_operation_id']])->fetchColumn()){throw new HttpError(409,'SERVICE_OPERATION_IN_FLIGHT');}if($this->db->execute("SELECT 1 FROM svc_package_changes WHERE service_id=? AND status IN ('AWAITING_PAYMENT','PENDING_PROVIDER','UNKNOWN')",[$id])->fetchColumn()||$this->db->execute("SELECT 1 FROM svc_renewals WHERE service_id=? AND status IN ('AWAITING_PAYMENT','PENDING_PROVIDER','UNKNOWN')",[$id])->fetchColumn()){throw new HttpError(409,'SERVICE_FINANCIAL_OPERATION_IN_FLIGHT');}
            $plan=$this->plan($id,$customer,$selection,$actor,$now);$quote=$this->commerce->quotes->issue($plan['quote']);$order=$this->commerce->orders->submit($quote['id'],$customer,['name'=>'Service package change','currency'=>$quote['currency']],$actor,$trace,$now);$change=Id::uuid();$price=Id::uuid();$line=$plan['target'];$key=base64_decode($this->config->key,true);$this->db->execute('INSERT INTO svc_prices(id,service_id,customer_id,currency,net_minor,tax_minor,total_minor,snapshot) VALUES (?,?,?,?,?,?,?,?)',[$price,$id,$customer,$quote['currency'],$line['net_minor'],$line['tax_minor'],$line['total_minor'],CanonicalJson::encode($line)]);$this->db->execute('INSERT INTO svc_package_changes(id,service_id,customer_id,service_version,period_id,order_id,target_price_id,target_encrypted) VALUES (?,?,?,?,?,?,?,?)',[$change,$id,$customer,(int)$service['version']+1,$service['current_period_id'],$order['id'],$price,(new Crypto($key))->encrypt(CanonicalJson::encode(['original_line'=>$line,'selection'=>$selection]),'svc-package:'.$change)]);$this->db->execute('UPDATE svc_services SET version=version+1 WHERE id=?',[$id]);$this->repository->event($service,'PACKAGE_CHANGE_REQUESTED',$actor,$trace);return $this->db->execute('SELECT * FROM svc_package_changes WHERE id=?',[$change])->fetch();
        });
    }
    public function verifyPayment(string $change,string $customer): array
    {
        $this->db->requireTransaction();$row=$this->db->execute('SELECT * FROM svc_package_changes WHERE id=? AND customer_id=? FOR UPDATE',[$change,$customer])->fetch();if(!$row){throw new HttpError(404,'PACKAGE_CHANGE_NOT_FOUND');}$order=$this->commerce->orders->repository->find($row['order_id'],$customer,true);$bill=$this->commerce->billing->repository->request($order['payment_request_id'],$customer,true);if($bill['status']!=='PAID'||$bill['refund_status']!=='NONE'||$order['refund_status']!=='NONE'||$order['status']==='CANCELLED'){throw new HttpError(409,'PACKAGE_PAYMENT_REQUIRED');}return $row;
    }
    public function preparePaid(string $change,Principal $actor,string $trace): string
    {
        $identity=$this->db->execute('SELECT * FROM svc_package_changes WHERE id=?',[$change])->fetch();if(!$identity){throw new HttpError(404,'PACKAGE_CHANGE_NOT_FOUND');}$this->authorize($identity['service_id'],$identity['customer_id'],$actor);return $this->transaction(function()use($identity,$change,$actor,$trace): string{
            $service=$this->lock($identity['service_id'],$identity['customer_id']);$row=$this->verifyPayment($change,$service['customer_id']);if($row['operation_id']!==null){return $row['operation_id'];}if($service['version']!==$row['service_version']||$service['current_period_id']!==$row['period_id']){throw new HttpError(409,'PACKAGE_SERVICE_CHANGED');}
            if($service['current_operation_id']!==null&&$this->db->execute("SELECT 1 FROM svc_operations o WHERE o.id=? AND (o.status IN ('PENDING','RUNNING') OR (o.status='UNKNOWN' AND NOT EXISTS(SELECT 1 FROM svc_resolutions r WHERE r.operation_id=o.id)))",[$service['current_operation_id']])->fetchColumn()){throw new HttpError(409,'SERVICE_OPERATION_IN_FLIGHT');}$key=base64_decode($this->config->key,true);$target=json_decode((new Crypto($key))->decrypt($row['target_encrypted'],'svc-package:'.$change),true,64,JSON_THROW_ON_ERROR);$resource=$this->db->execute("SELECT * FROM svc_resources WHERE service_id=? AND resource_role='PRIMARY'",[$service['id']])->fetch();if(!$resource){throw new HttpError(409,'SERVICE_RESOURCE_MISSING');}$mapping=(new \Hostider\Hosting\Pools($this->db,$this->config))->existingMapping($resource['server_id'],$target['selection']['product_id'],$target['selection']);$reservation=$this->db->execute('SELECT reseller_scope FROM hosting_reservations WHERE operation_id=?',[$resource['operation_id']])->fetch();if(!$reservation||$reservation['reseller_scope']!==$mapping['reseller_scope']){throw new HttpError(409,'PACKAGE_RESELLER_SCOPE_REVIEW_REQUIRED');}
            $id=Id::uuid();$provider=Id::uuid();$generation=1+(int)$this->db->execute("SELECT COALESCE(MAX(generation),0) FROM svc_operations WHERE order_item_id=? AND kind='CHANGE_PACKAGE'",[$service['order_item_id']])->fetchColumn();$request=CanonicalJson::encode(['kind'=>'CHANGE_PACKAGE','method'=>'changePackage','service_id'=>$service['id'],'resource_id'=>$resource['external_id'],'server_id'=>$resource['server_id'],'expected_status'=>$service['status'],'package_change_id'=>$change,'provider_config'=>['package_name'=>$mapping['package_name']]]);$hash=hash_hmac('sha256',$request,$key);$this->db->execute("INSERT INTO svc_operations(id,service_id,order_item_id,kind,generation,request_fingerprint) VALUES (?,?,?,'CHANGE_PACKAGE',?,?)",[$id,$service['id'],$service['order_item_id'],$generation,$hash]);$this->db->execute('INSERT INTO svc_provider_operations(id,lifecycle_operation_id,server_id,request_encrypted,request_fingerprint) VALUES (?,?,?,?,?)',[$provider,$id,$resource['server_id'],(new Crypto($key))->encrypt($request,'svc-operation:'.$provider),$hash]);$this->db->execute("UPDATE svc_package_changes SET operation_id=?,status='PENDING_PROVIDER' WHERE id=?",[$id,$change]);$this->db->execute('UPDATE svc_services SET current_operation_id=?,version=version+1 WHERE id=?',[$id,$service['id']]);(new \Hostider\Core\Queue\Outbox($this->db,new \Hostider\Core\Queue\Queue($this->db)))->append(Id::uuid(),'services.action',$id,['operation_id'=>$id],$trace);$this->repository->event($service,'PACKAGE_PROVIDER_QUEUED',$actor,$trace);return $id;
        });
    }
    public function complete(array $service,string $change,bool $success,bool $reconciliation=false): void
    {
        $this->db->requireTransaction();$row=$this->verifyPayment($change,$service['customer_id']);if($row['status']!==($reconciliation?'UNKNOWN':'PENDING_PROVIDER')||$row['period_id']!==$service['current_period_id']){throw new HttpError(409,'PACKAGE_COMPLETION_CONFLICT');}if($success){$key=base64_decode($this->config->key,true);$target=json_decode((new Crypto($key))->decrypt($row['target_encrypted'],'svc-package:'.$change),true,64,JSON_THROW_ON_ERROR);$this->repository->saveConfig($service['id'],$target);$this->db->execute('UPDATE svc_services SET product_id=?,category_id=?,name=?,current_price_id=? WHERE id=?',[$target['selection']['product_id'],$this->commerce->catalog->repository->product($target['selection']['product_id'])['category_id'],$target['original_line']['name'],$row['target_price_id'],$service['id']]);}$this->db->execute('UPDATE svc_package_changes SET status=? WHERE id=?',[$success?'VERIFIED':'FAILED',$change]);
    }
}
